insert into public.learning_cards (lesson_id, position, title, blocks) values ('708e7972-ea95-5275-b834-83bd8879c70b', 1, 'Six amis', '[{"type":"keyfigure","value":"10","label":"Saisons de Friends, de 1994 à 2004"},{"type":"text","text":"Rachel, Ross, Monica, Chandler, Joey et Phoebe se retrouvent au Central Perk, un café de New York."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('708e7972-ea95-5275-b834-83bd8879c70b', 2, 'D’oh !', '[{"type":"text","text":"Matt Groening crée les Simpson, famille jaune de Springfield. Depuis 1989, la série bat tous les records de longévité."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('708e7972-ea95-5275-b834-83bd8879c70b', 3, 'Deux bureaux', '[{"type":"text","text":"The Office naît au Royaume-Uni en 2001 avec Ricky Gervais. La version américaine, en 2005, suit Michael Scott, patron gênant d’une entreprise de papier à Scranton."}]'::jsonb);
